	private static RowState row(EntryState state, ConstantSlotCase testCase) {
		NativeSlotLayout layout = new NativeSlotLayout(
				Map.of("subject", 0, "predicate", 1, "object", 2, "unused", 3, "context", 4), null);
		layout.freeze(List.of("subject", "predicate", "object", "unused", "context"));
		RowState row = new RowState(new TestSource(), layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN);
		if (state != EntryState.FRESH) {
			row.slots[testCase.boundSlot] = state == EntryState.COMPATIBLE ? testCase.constant : testCase.constant + 1L;
		}
		row.recomputeBoundMask();
		return row;
	}

	private static RowState freshRow() {
		return freshRow(new TestSource());
	}

	private static RowState freshRow(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(
				Map.of("subject", 0, "predicate", 1, "object", 2, "unused", 3, "context", 4), null);
		layout.freeze(List.of("subject", "predicate", "object", "unused", "context"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, UNKNOWN);
		row.recomputeBoundMask();
		return row;
	}

	private static List<String> expectedRows(ConstantSlotCase testCase, EntryState state,
			LmdbNativeKernelLowering.Lowered lowered) {
		if (state == EntryState.CONFLICTING) {
			return List.of();
		}
		Emit emit = (Emit) lowered.kernel.terminal;
		List<String> result = new ArrayList<>();
		for (long[] sourceRow : testCase.expectedRows) {
			long[] projected = new long[emit.cols.length];
			for (int i = 0; i < emit.cols.length; i++) {
				int column = emit.cols[i];
				assertThat(column).isLessThan(lowered.bindings.columnEngineSlots.length);
				projected[i] = sourceRow[lowered.bindings.columnEngineSlots[column]];
			}
			result.add(Arrays.toString(projected));
		}
		result.sort(String::compareTo);
		return result;
	}

	private static List<String> run(LmdbNativeKernelLowering.Lowered lowered, ConstantSlotCase testCase,
			RowState row, boolean compiled) throws Exception {
		NativeLmdbQuerySource.NativeAdjacency[] views = new NativeLmdbQuerySource.NativeAdjacency[lowered.bindings.adjacencies.length];
		Map<ViewKey, NativeLmdbQuerySource.NativeAdjacency> availableViews = new HashMap<>();
		for (int i = 0; i < views.length; i++) {
			views[i] = lowered.bindings.adjacencies[i].bySubject ? testCase.bySubject : testCase.byObject;
			availableViews.put(new ViewKey(lowered.bindings.adjacencies[i].predicate,
					lowered.bindings.adjacencies[i].bySubject), views[i]);
		}
		Map<DomainKey, long[]> availableDomains = new HashMap<>();
		for (LmdbNativeKernelBindings.DomainRequest request : lowered.bindings.keyDomains) {
			if (request.literal == null) {
				availableDomains.put(new DomainKey(request.predicate, request.key, request.bySubject), testCase.domain);
			}
		}
		return run(lowered, row, availableViews, availableDomains, compiled);
	}

	private static void assertLoweredPlanParity(SlotPlan plan, RowState row,
			Map<ViewKey, NativeLmdbQuerySource.NativeAdjacency> views, Map<DomainKey, long[]> domains,
			long[][] logicalRows) throws Exception {
		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(plan, row, null);
		assertThat(lowered)
				.as("actual SlotPlan algebra must lower to a directly executable native kernel: %s", plan)
				.isNotNull();
		assertThat(lowered.bindings.planRequests)
				.as("the constant-slot matrix must exercise native lowering rather than a semantic plan bridge")
				.isEmpty();
		List<String> expected = expectedRows(lowered, logicalRows);
		for (boolean compiled : new boolean[] { false, true }) {
			List<String> actual = run(lowered, row, views, domains, compiled);
			assertThat(actual)
					.as("%s rows for lowered %s", compiled ? "generated" : "interpreted", plan)
					.containsExactlyElementsOf(expected);
		}
	}

	private static void assertPlanRowsParity(SlotPlan plan, RowState row,
			Map<ViewKey, NativeLmdbQuerySource.NativeAdjacency> views, Map<DomainKey, long[]> domains,
			long[][] logicalRows) throws Exception {
		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(plan, row, null);
		assertThat(lowered)
				.as("the intentionally semantic MINUS arm must still lower to an executable kernel: %s", plan)
				.isNotNull();
		assertThat(lowered.bindings.planRequests)
				.as("a UNION right arm is represented by one exact PlanRows producer")
				.hasSize(1);
		assertThat(lowered.kernel.pipeline)
				.as("the MINUS UNION arm must be visible as a PlanRows instruction")
				.anyMatch(LmdbNativeKernelIr.PlanRows.class::isInstance);
		List<String> expected = expectedRows(lowered, logicalRows);
		for (boolean compiled : new boolean[] { false, true }) {
			List<String> actual = run(lowered, row, views, domains, compiled);
			assertThat(actual)
					.as("%s rows for PlanRows-backed lowered %s", compiled ? "generated" : "interpreted", plan)
					.containsExactlyElementsOf(expected);
		}
	}

	private static List<String> expectedRows(LmdbNativeKernelLowering.Lowered lowered, long[][] logicalRows) {
		assertThat(lowered.kernel.terminal)
				.as("row lowering must retain an explicit emission terminal")
				.isInstanceOf(Emit.class);
		Emit emit = (Emit) lowered.kernel.terminal;
		List<String> result = new ArrayList<>();
		for (long[] sourceRow : logicalRows) {
			long[] projected = new long[emit.cols.length];
			for (int i = 0; i < emit.cols.length; i++) {
				int column = emit.cols[i];
				assertThat(column).isLessThan(lowered.bindings.columnEngineSlots.length);
				int engineSlot = lowered.bindings.columnEngineSlots[column];
				assertThat(engineSlot).isLessThan(sourceRow.length);
				projected[i] = sourceRow[engineSlot];
			}
			result.add(Arrays.toString(projected));
		}
		result.sort(String::compareTo);
		return result;
	}

	private static List<String> run(LmdbNativeKernelLowering.Lowered lowered, RowState row,
			Map<ViewKey, NativeLmdbQuerySource.NativeAdjacency> availableViews,
			Map<DomainKey, long[]> availableDomains, boolean compiled) throws Exception {
		NativeLmdbQuerySource.NativeAdjacency[] views = new NativeLmdbQuerySource.NativeAdjacency[lowered.bindings.adjacencies.length];
		for (int i = 0; i < views.length; i++) {
			LmdbNativeKernelBindings.AdjacencyRequest request = lowered.bindings.adjacencies[i];
			views[i] = availableViews.get(new ViewKey(request.predicate, request.bySubject));
			assertThat(views[i])
					.as("missing fixture view for predicate %s/%s", request.predicate, request.bySubject)
					.isNotNull();
		}
		long[][] domains = new long[lowered.bindings.keyDomains.length][];
		for (int i = 0; i < domains.length; i++) {
			LmdbNativeKernelBindings.DomainRequest request = lowered.bindings.keyDomains[i];
			long[] values = request.literal == null
					? availableDomains.get(new DomainKey(request.predicate, request.key, request.bySubject))
					: request.literal;
			assertThat(values)
					.as("missing fixture domain for predicate %s/%s and key %s", request.predicate, request.bySubject,
							request.key)
					.isNotNull();
			domains[i] = values.clone();
		}
		RowState runtimeRow = row.fork();
		LmdbNativeKernelHooks hooks = new LmdbNativeKernelHooks(runtimeRow, lowered.bindings);
		int[] offsets = new int[domains.length];
		int[] lengths = new int[domains.length];
		for (int i = 0; i < domains.length; i++) {
			lengths[i] = domains[i].length;
		}
		LmdbNativeKernelBindings.BoundDomains boundDomains = new LmdbNativeKernelBindings.BoundDomains(domains, offsets,
				lengths);
		KernelContext context = lowered.bindings.context(views, boundDomains, runtimeRow, hooks);
		JaninoKernel kernel = compiled ? KernelCompilationTestSupport.compile(lowered.kernel)
				: LmdbNativeKernelInterpreter.forRows(lowered.kernel);
		assertThat(kernel).as("kernel tier declined %s", compiled ? "generated" : "interpreted").isNotNull();
		try {
			kernel.bind(context);
			return drain(kernel, lowered.kernel.stride());
		} finally {
			kernel.close();
			hooks.closeFilters();
		}
	}

	private static List<String> drain(JaninoKernel kernel, int stride) {
		List<String> rows = new ArrayList<>();
		long[] buffer = new long[Math.max(1, stride)];
		for (int fill = 0; fill < 100; fill++) {
			int count = kernel.fill(buffer, 1);
			assertThat(count).isBetween(0, 1);
			if (count == 0) {
				rows.sort(String::compareTo);
				return rows;
			}
			rows.add(Arrays.toString(Arrays.copyOf(buffer, stride)));
		}
		throw new AssertionError("kernel did not exhaust after 100 fills");
	}

